import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Indexing Management","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Local Drives","slug":"_1-local-drives","link":"#_1-local-drives","children":[]},{"level":2,"title":"2. Network Drives","slug":"_2-network-drives","link":"#_2-network-drives","children":[]},{"level":2,"title":"3. WSL (Windows Subsystem for Linux)","slug":"_3-wsl-windows-subsystem-for-linux","link":"#_3-wsl-windows-subsystem-for-linux","children":[]},{"level":2,"title":"4. Folders","slug":"_4-folders","link":"#_4-folders","children":[]},{"level":2,"title":"5. Exclusions","slug":"_5-exclusions","link":"#_5-exclusions","children":[{"level":3,"title":"Path Exclusions","slug":"path-exclusions","link":"#path-exclusions","children":[]},{"level":3,"title":"Glob Rules","slug":"glob-rules","link":"#glob-rules","children":[]},{"level":3,"title":"Regex Rules","slug":"regex-rules","link":"#regex-rules","children":[]}]}],"relativePath":"user-guide/settings/index-drives.md","filePath":"user-guide/settings/index-drives.md","lastUpdated":1791112464000}`),a={name:`user-guide/settings/index-drives.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="indexing-management" tabindex="-1">Indexing Management <a class="header-anchor" href="#indexing-management" aria-label="Permalink to “Indexing Management”">​</a></h1><p>The Indexing settings page controls indexing scopes, refresh schedules, and exclusion rules across local hard drives, network shares, WSL distributions, and standalone folders. Top tabs include: <strong>Local Drives</strong>, <strong>Network Drives</strong>, <strong>WSL</strong> (shown only when distributions are detected), <strong>Folders</strong>, and <strong>Exclusions</strong>.</p><h2 id="_1-local-drives" tabindex="-1">1. Local Drives <a class="header-anchor" href="#_1-local-drives" aria-label="Permalink to “1. Local Drives”">​</a></h2><ul><li><strong>Top Status Card</strong>: Displays total indexed physical drives and item counts, with a global <strong>Rebuild Index</strong> button.</li><li><strong>Drive Row Items</strong>: <ul><li><strong>Enable / Disable Checkbox</strong>: Toggles indexing for each individual partition.</li><li><strong>Filesystem &amp; Status</strong>: Displays underlying filesystem (NTFS, ReFS, FAT32, exFAT), health state, and indexed count.</li><li><strong>Per-Drive Actions</strong>: Individual <strong>Rebuild</strong> and <strong>Remove</strong> buttons; displays a dynamic <strong>Stop</strong> button during active scans.</li></ul></li><li><strong>Real-Time Tracking</strong>: NTFS / ReFS volumes sync incrementally via Windows USN Change Journals; FAT32 / exFAT volumes monitor filesystem change events.</li><li><strong>Uninterrupted Rebuilds</strong>: While a drive is rebuilding, its existing index answers user queries until the new index completes and replaces it in one step. If interrupted, scanning resumes from the last checkpoint on the next launch.</li></ul><h2 id="_2-network-drives" tabindex="-1">2. Network Drives <a class="header-anchor" href="#_2-network-drives" aria-label="Permalink to “2. Network Drives”">​</a></h2><ul><li><strong>Network Storage Support</strong>: Lists all mapped Windows network drives (SMB / NAS).</li><li><strong>Refresh Mode</strong>: Network shares lack local USN journals and rely on scheduled polling: <ul><li><strong>Manual</strong> — Refreshes only when &quot;Rebuild Index&quot; is clicked.</li><li><strong>Every 15 Minutes</strong> — Recommended for active collaborative shares.</li><li><strong>Hourly</strong> — Balanced schedule.</li><li><strong>Daily</strong> — Ideal for static archival storage.</li></ul></li><li><strong>Symlink Loop Protection</strong>: Built-in cycle detection and ancestor stack algorithms automatically prevent infinite traversal caused by circular symbolic links or reparse points.</li></ul><h2 id="_3-wsl-windows-subsystem-for-linux" tabindex="-1">3. WSL (Windows Subsystem for Linux) <a class="header-anchor" href="#_3-wsl-windows-subsystem-for-linux" aria-label="Permalink to “3. WSL (Windows Subsystem for Linux)”">​</a></h2><p>Appears automatically whenever at least one WSL distribution is installed:</p><ul><li><strong>Auto-Discovery</strong>: Automatically recognizes Ubuntu, Debian, Arch, and other WSL distros.</li><li><strong>Status &amp; Schedules</strong>: Identical status cards and Refresh Mode options (Manual / 15 Min / Hourly / Daily).</li><li><strong>Zero-I/O Queries</strong>: WSL searches read the in-memory tree directly without waking or blocking the Linux subsystem.</li></ul><h2 id="_4-folders" tabindex="-1">4. Folders <a class="header-anchor" href="#_4-folders" aria-label="Permalink to “4. Folders”">​</a></h2><p>Use standalone folder indexing when you want to target specific working directories instead of entire volumes or NAS shares:</p><ul><li><strong>Multi-Select Addition</strong>: Click <strong>Add Folder</strong> to open a native picker supporting <code>Ctrl</code> / <code>Shift</code> batch selection.</li><li><strong>UNC Path Support</strong>: Add network UNC share paths directly (e.g. <code>\\\\server\\share\\projects</code>).</li><li><strong>Independent Schedules</strong>: Each folder has its own toggle, item counter, and Refresh Mode dropdown.</li></ul><h2 id="_5-exclusions" tabindex="-1">5. Exclusions <a class="header-anchor" href="#_5-exclusions" aria-label="Permalink to “5. Exclusions”">​</a></h2><p>Exclusion rules filter search results and bound how far the network, WSL and folder-index walks descend. They do not stop a local drive from being indexed: a local volume is always walked in full, so a path such as <code>E:\\</code> in this list only hides its results. To stop indexing a local drive, turn it off under <strong>Local Drives</strong> above. The rules are organized into three sub-tabs:</p><h3 id="path-exclusions" tabindex="-1">Path Exclusions <a class="header-anchor" href="#path-exclusions" aria-label="Permalink to “Path Exclusions”">​</a></h3><ul><li><strong>Matching Logic</strong>: Prefix matching against absolute physical paths.</li><li><strong>Environment Variables</strong>: Accepts <code>%ProgramData%</code>, <code>%APPDATA%</code>, or <code>D:\\Cache</code>.</li></ul><h3 id="glob-rules" tabindex="-1">Glob Rules <a class="header-anchor" href="#glob-rules" aria-label="Permalink to “Glob Rules”">​</a></h3><ul><li><strong>Syntax</strong>: <ul><li><code>*</code>: Matches characters within a single folder level (e.g. <code>*.tmp</code>, <code>*.log</code>).</li><li><code>**</code>: Matches recursively across subdirectories (e.g. <code>**/node_modules/**</code>, <code>**/bin/**</code>, <code>**/obj/**</code>).</li></ul></li></ul><h3 id="regex-rules" tabindex="-1">Regex Rules <a class="header-anchor" href="#regex-rules" aria-label="Permalink to “Regex Rules”">​</a></h3><ul><li><strong>Advanced Filtering</strong>: Regular expression matching against paths and filenames (e.g. <code>^\\.</code> for hidden dotfiles, <code>~\\$</code> for temporary Office locks).</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Exclusions support both <strong>single entry additions</strong> and <strong>batch editing</strong>: click <strong>Generate from List</strong> to export rules to text, edit, and click <strong>Apply to List</strong> to update in bulk. Modified exclusion rules automatically trigger index filtering.</p></div>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};